// Package embedded exposes the repo source bundled into the report-rex binary at
// build time. The contents of data/ are generated by scripts/prepare-embed.sh —
// never edit files under data/ directly, and never commit them (see cli/.gitignore).
package embedded

import (
	"embed"
	"io/fs"
)

// "all:" is required so go:embed includes dotfiles (.vale.ini) — by default it
// skips any file or directory whose name starts with "." or "_".
//
//go:embed all:data/build-context
var buildContext embed.FS

//go:embed all:data/scaffolds
var scaffolds embed.FS

//go:embed all:data/editors
var editors embed.FS

//go:embed all:data/vuln-templates
var vulnTemplates embed.FS

// BuildContextFS returns the Docker build context (Dockerfile, core/, templates/,
// styles/, .vale.ini) rooted at its own directory, ready to pass to `docker build`.
func BuildContextFS() fs.FS {
	sub, err := fs.Sub(buildContext, "data/build-context")
	if err != nil {
		panic(err) // programmer error: data/build-context is always embedded
	}
	return sub
}

// ScaffoldFS returns the `report init` scaffold trees, rooted at its own directory.
// Sub-paths are "full-report" and "quick-comm/<kind>".
func ScaffoldFS() fs.FS {
	sub, err := fs.Sub(scaffolds, "data/scaffolds")
	if err != nil {
		panic(err) // programmer error: data/scaffolds is always embedded
	}
	return sub
}

// EditorsFS returns the `rex editor-conf` editor integration sources, rooted
// at its own directory. Sub-paths are per-editor, e.g. "nvim".
func EditorsFS() fs.FS {
	sub, err := fs.Sub(editors, "data/editors")
	if err != nil {
		panic(err) // programmer error: data/editors is always embedded
	}
	return sub
}

// VulnTemplatesFS returns the vuln-templates/ finding write-up stubs used by
// `rex report section vuln --template`, rooted at its own directory.
func VulnTemplatesFS() fs.FS {
	sub, err := fs.Sub(vulnTemplates, "data/vuln-templates")
	if err != nil {
		panic(err) // programmer error: data/vuln-templates is always embedded
	}
	return sub
}
